#![no_std]
use super::core::{AdapterState,AndroidDriverAdapter,CoreError,DriverAdapter,DriverSlot,HardwareInfo};
use super::universal::{DriverAbi,DriverAction,DriverOs};
pub struct AndroidLayer<A>{pub slot:DriverSlot<A>}
impl<A:AndroidDriverAdapter>AndroidLayer<A>{pub const fn new(adapter:A)->Self{Self{slot:DriverSlot::new(adapter)}}pub fn validate(&self,hw:&HardwareInfo)->Result<(),CoreError>{let id=self.slot.adapter.identity();if id.os!=DriverOs::Android||id.abi!=DriverAbi::AndroidHal{return Err(CoreError::UnsupportedAbi)}let api=self.slot.adapter.android_hal_version();if id.api_version==0||api==0||api>u32::from(u16::MAX)||id.api_version!=api as u16{return Err(CoreError::InvalidRequest)}let name=self.slot.adapter.android_interface_name();if name.len()<3||name.len()>127||!name.as_bytes().iter().all(|b|b.is_ascii_graphic()||*b==b'/'||*b==b'.'||*b==b'_'){return Err(CoreError::InvalidRequest)}if !id.matches(hw)||!hw.valid()||hw.irq==u32::MAX{return Err(CoreError::InvalidDevice)}Ok(())}pub fn can_probe(&self,hw:&HardwareInfo)->bool{self.slot.state==AdapterState::New&&self.validate(hw).is_ok()}pub fn probe<H:super::core::HardwareAbstraction>(&mut self,hw:&HardwareInfo,hal:&mut H)->Result<(),CoreError>{if !self.can_probe(hw){return Err(CoreError::InvalidDevice)}self.slot.dispatch(DriverAction::Probe,hw,hal)}pub fn start<H:super::core::HardwareAbstraction>(&mut self,hw:&HardwareInfo,hal:&mut H)->Result<(),CoreError>{self.slot.dispatch(DriverAction::Start,hw,hal)}pub fn stop<H:super::core::HardwareAbstraction>(&mut self,hw:&HardwareInfo,hal:&mut H)->Result<(),CoreError>{self.slot.dispatch(DriverAction::Stop,hw,hal)}pub fn remove<H:super::core::HardwareAbstraction>(&mut self,hw:&HardwareInfo,hal:&mut H)->Result<(),CoreError>{self.slot.dispatch(DriverAction::Remove,hw,hal)}}
#[cfg(test)]mod tests{use super::*;use super::super::bus::DeviceId;struct Mock{api:u32,name:&'static str}impl DriverAdapter for Mock{fn identity(&self)->super::super::core::DriverIdentity{super::super::core::DriverIdentity{os:DriverOs::Android,abi:DriverAbi::AndroidHal,api_version:self.api as u16,vendor:1,device:2,signed:true}}fn probe(&mut self,_:&HardwareInfo)->Result<(),CoreError>{Ok(())}fn start(&mut self,_:&HardwareInfo)->Result<(),CoreError>{Ok(())}fn stop(&mut self,_:&HardwareInfo)->Result<(),CoreError>{Ok(())}fn remove(&mut self,_:&HardwareInfo)->Result<(),CoreError>{Ok(())}}impl AndroidDriverAdapter for Mock{fn android_hal_version(&self)->u32{self.api}fn android_interface_name(&self)->&'static str{self.name}}struct Hal;impl super::super::core::HardwareAbstraction for Hal{fn mmio_read32(&self,_:&HardwareInfo,_:u64)->Result<u32,CoreError>{Ok(0)}fn mmio_write32(&mut self,_:&HardwareInfo,_:u64,_:u32)->Result<(),CoreError>{Ok(())}fn irq_ack(&mut self,_:&HardwareInfo)->Result<(),CoreError>{Ok(())}fn dma_submit(&mut self,_:&HardwareInfo,_:u64)->Result<(),CoreError>{Ok(())}}fn hw()->HardwareInfo{HardwareInfo{id:DeviceId{vendor:1,device:2,class:0,revision:1},mmio_base:0x1000,mmio_length:0x100,irq:5,dma_bits:64}}#[test]fn lifecycle_executes(){let mut a=AndroidLayer::new(Mock{api:7,name:"vendor/awe-hal"});let mut h=Hal;a.probe(&hw(),&mut h).unwrap();a.start(&hw(),&mut h).unwrap();a.stop(&hw(),&mut h).unwrap();a.remove(&hw(),&mut h).unwrap();assert_eq!(a.slot.state,AdapterState::Removed)}#[test]fn malformed_name_is_rejected(){let a=AndroidLayer::new(Mock{api:7,name:"bad name"});assert!(!a.can_probe(&hw()));}}
